class Solution { private List<Integer>[] graph;private int[] count,answer;private int n;public int[] sumOfDistancesInTree(int n,int[][] edges){this.n=n;graph=new List[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}count=new int[n];Arrays.fill(count,1);answer=new int[n];post(0,-1);pre(0,-1);return answer;}private void post(int node,int parent){for(int next:graph[node])if(next!=parent){post(next,node);count[node]+=count[next];answer[node]+=answer[next]+count[next];}}private void pre(int node,int parent){for(int next:graph[node])if(next!=parent){answer[next]=answer[node]-count[next]+n-count[next];pre(next,node);}} }
